select order_id, `select` as escaped_identifier, amount + shipping_fee - discount_amount as payable_amount, round(amount * exchange_rate, 2) as converted_amount, cast(created_at as date) as created_date, try_cast(raw_amount as decimal(18, 2)) as parsed_amount, coalesce(customer_name, contact_name, 'unknown') as display_name, nullif(trim(phone_number), '') as normalized_phone, concat_ws( '-', cast(region_id as string), lpad(cast(customer_id as string), 10, '0') ) as customer_key, regexp_replace(lower(trim(email)), '\\s+', '') as normalized_email from style_lab.fact_order;
